package codegen

import (
	"bytes"
	"errors"
	"fmt"
	"go/format"
	"io/fs"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"unicode"
)

// File is one generated file.
type File struct {
	// Path is relative to the repository root, with forward slashes.
	Path string
	// Content is the complete file.
	Content []byte
}

// Lang selects the comment syntax and licence of a generated file's header.
type Lang int

// Languages the generators write.
const (
	LangGo Lang = iota + 1
	LangDart
	LangTS
	LangMarkdown
)

// header returns the licence header and the generated-code marker. Studio
// code is AGPL-3.0-only (ADR-0022); everything else is Apache-2.0. The
// marker follows https://go.dev/s/generatedcode in every language, which is
// what covgate and the linters recognise.
func header(lang Lang, source string) string { //nolint:unparam // each generator passes its own source; more arrive with the schema generators.
	licence := "Apache-2.0"
	if lang == LangTS {
		licence = "AGPL-3.0-only"
	}
	marker := fmt.Sprintf("Code generated by schemagen from %s. DO NOT EDIT.", source)
	if lang == LangMarkdown {
		return "<!-- " + marker + " -->\n\n"
	}
	return "// SPDX-FileCopyrightText: 2026 Plux contributors\n// SPDX-License-Identifier: " + licence +
		"\n\n// " + marker + "\n\n"
}

// goFile formats Go source with gofmt and returns it as a File.
func goFile(path string, src []byte) (File, error) {
	formatted, err := format.Source(src)
	if err != nil {
		return File{}, fmt.Errorf("codegen: gofmt %s: %w\n%s", path, err, src)
	}
	return File{Path: path, Content: formatted}, nil
}

// WriteAll writes the files under root and returns the paths whose content
// changed. Unchanged files are not touched, so timestamps stay stable.
func WriteAll(root string, files []File) ([]string, error) {
	var changed []string
	for _, f := range files {
		path := filepath.Join(root, filepath.FromSlash(f.Path))
		old, err := os.ReadFile(path)
		if err != nil && !errors.Is(err, fs.ErrNotExist) {
			return changed, fmt.Errorf("codegen.WriteAll: %w", err)
		}
		if err == nil && bytes.Equal(old, f.Content) {
			continue
		}
		if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
			return changed, fmt.Errorf("codegen.WriteAll: %w", err)
		}
		if err := os.WriteFile(path, f.Content, 0o644); err != nil { //nolint:gosec // G306: generated sources are world-readable.
			return changed, fmt.Errorf("codegen.WriteAll: %w", err)
		}
		changed = append(changed, f.Path)
	}
	return changed, nil
}

// initialisms are rendered in upper case in Go identifiers (go-standards §3).
var initialisms = []string{"id", "json", "pxl", "url", "uri", "ui", "dpop", "http", "api", "ios", "sse", "db", "kv"}

// words splits a key such as "bundle.pageSectionSize" or "on-enter" into
// lower-case words.
func words(key string) []string {
	var out []string
	var cur strings.Builder
	flush := func() {
		if cur.Len() > 0 {
			out = append(out, strings.ToLower(cur.String()))
			cur.Reset()
		}
	}
	for _, r := range key {
		switch {
		case r == '.' || r == '-' || r == '_' || r == ' ':
			flush()
		case unicode.IsUpper(r):
			flush()
			cur.WriteRune(r)
		default:
			cur.WriteRune(r)
		}
	}
	flush()
	return out
}

// GoName returns the exported Go identifier for a key, with initialisms in
// upper case: "pxl.operationBudget" → "PXLOperationBudget".
func GoName(key string) string {
	var b strings.Builder
	for _, w := range words(key) {
		if slices.Contains(initialisms, w) {
			b.WriteString(strings.ToUpper(w))
			continue
		}
		b.WriteString(strings.ToUpper(w[:1]) + w[1:])
	}
	return b.String()
}

// LowerCamel returns the lowerCamelCase identifier for a key, as Dart and
// TypeScript use: "pxl.operationBudget" → "pxlOperationBudget".
func LowerCamel(key string) string {
	ws := words(key)
	for i := 1; i < len(ws); i++ {
		ws[i] = strings.ToUpper(ws[i][:1]) + ws[i][1:]
	}
	return strings.Join(ws, "")
}

// quoteDart returns s as a single-quoted Dart string literal.
func quoteDart(s string) string {
	r := strings.NewReplacer(`\`, `\\`, `'`, `\'`, "$", `\$`, "\n", `\n`)
	return "'" + r.Replace(s) + "'"
}

// wrapComment wraps text into comment lines of at most width columns, each
// starting with prefix.
func wrapComment(prefix, text string, width int) string {
	var b strings.Builder
	line := prefix
	for _, w := range strings.Fields(text) {
		if len(line) > len(prefix) && len(line)+1+len(w) > width {
			b.WriteString(strings.TrimRight(line, " ") + "\n")
			line = prefix
		}
		if len(line) > len(prefix) {
			line += " "
		}
		line += w
	}
	b.WriteString(line + "\n")
	return b.String()
}
